'use client';

import { HlsAudioAdapter, type HlsAudioAdapterProps } from '@videojs/spf/adapters/hls-audio';
import { type AudioHTMLAttributes, forwardRef, type ReactNode } from 'react';

import { useAttachMedia } from '../../utils/use-attach-media';
import { useComposedRefs } from '../../utils/use-composed-refs';
import { useMediaInstance } from '../../utils/use-media-instance';
import { type MediaRefProps, useMediaRef } from '../../utils/use-media-ref';
import { useSyncProps } from '../../utils/use-sync-props';
import { type MediaFallbackProps, audioFallback } from '../fallback';

export interface HlsAudioProps
  extends
    Omit<AudioHTMLAttributes<HTMLAudioElement>, keyof HlsAudioAdapterProps>,
    Partial<HlsAudioAdapterProps>,
    MediaRefProps<HlsAudioAdapter>,
    MediaFallbackProps {
  children?: ReactNode;
}

export const HlsAudio = forwardRef<HTMLAudioElement, HlsAudioProps>(function HlsAudio(
  { children, fallback = audioFallback, mediaRef, ...props },
  ref
) {
  const media = useMediaInstance(HlsAudioAdapter);
  const attachRef = useAttachMedia(media);
  const exposeRef = useMediaRef(media, mediaRef);
  const composedRef = useComposedRefs(attachRef, exposeRef, ref);
  const htmlProps = useSyncProps(media, props, HlsAudioAdapter.defaultProps);

  return (
    <audio ref={composedRef} {...htmlProps} crossOrigin={props.crossOrigin ?? undefined}>
      {children}
      {fallback}
    </audio>
  );
});

export namespace HlsAudio {
  export type Props = HlsAudioProps;
}
